import { defineChapterTopic, type ChapterAuthorSpec } from '../chapter-package-engine';
import type { EducationTopic } from '../education-types';
import type { VERIFIED_SOURCES } from '../verified-sources';

const ANAT_DISCLOSURE = {
  status: 'partial' as const,
  summary:
    'Integrated with Anatomy 360’s 2,401-mesh 5-layer atlas: 2,301 Male active meshes (2,234 BodyParts3D 4.0 + 47 Shared Enhancements + 20 Male Enhancements) and 2,328 Female active default meshes (2,189 reused male-base + 47 Shared + 92 Female Overlay v3.0 [84 HuBMAP HRA CC BY 4.0 + 8 co-registered reconstructions], 133.8k triangles; +8 optional pregnancy parts), 12 System Lessons, and Surgical Layer Dissections. Remaining gaps include thyroid/parathyroid glands, middle/inner ear ossicles & cochlea, thoracic duct & regional lymph nodes, and non-pelvic female-specific geometry.',
  missingAssets: [
    'Micro-scale 3D surface geometry for cranial meninges, parathyroid glands, inner-ear ossicles, and fine peripheral nerve plexuses',
  ],
};

function makeAnatChapter(
  num: number,
  id: string,
  chapterTitle: string,
  title: string,
  summary: string,
  meshNote: string,
  readKeys: (keyof typeof VERIFIED_SOURCES)[],
  comp: { colA: string; colB: string; rows: ChapterAuthorSpec['comparisonTable']['rows'] },
  mechanisms: string[],
  clinical: string,
  fmas: string[],
  sys: ChapterAuthorSpec['relatedSystems'],
  mcqs: ChapterAuthorSpec['selfChecks'],
): ChapterAuthorSpec {
  return {
    id,
    domainId: 'human_anatomy',
    chapterCode: `A${num}`,
    chapterOrder: num,
    chapterTitle,
    title,
    summary,
    targetTracks: ['school_foundations', 'secondary_premed', 'medical_foundations', 'clinical_applied', 'allied_health', 'graduate_research'],
    curriculumMappings: [
      { frameworkId: 'pk_ncp_gs_4_8', gradeOrYear: 'Grades 6–8', unitOrModule: `Body Systems Orientation (${chapterTitle})`, status: 'compulsory' },
      { frameworkId: 'pk_ncp_bio_9_12', gradeOrYear: 'Grades XI–XII', unitOrModule: `Human Structural Organization (${chapterTitle})`, status: 'elective' },
      { frameworkId: 'pk_pmdc_mbbs', gradeOrYear: 'MBBS Years 1–2', unitOrModule: `Gross, Regional & Neuroanatomy (${chapterTitle})`, status: 'compulsory' },
      { frameworkId: 'anat_soc_core', gradeOrYear: 'Undergraduate / Preclinical', unitOrModule: `Anatomical Society Core (${chapterTitle})`, status: 'recommended' },
    ],
    prerequisites: ['Anatomical position & orthogonal planes (A1)'],
    learningObjectives: [
      `Locate and describe the 3D spatial boundaries, attachments, and neurovascular relations within ${chapterTitle.toLowerCase()}.`,
      `Distinguish surface landmarks, osteofascial compartments, and lymphatic/venous drainage patterns (${meshNote}).`,
      `Apply regional anatomical relationships to nerve injury syndromes, surgical approaches, and cross-sectional radiological slices.`,
    ],
    depthExplanations: {
      school_foundations: `${summary} Exploring these structures inside the 3D Anatomy Explorer helps visualize how bones, muscles, vessels, and organs fit safely inside the human body.`,
      secondary_premed: `${summary} Every organ system exhibits spatial hierarchy—matching surface protection, dual arterial perfusion or portal drainage, and protective bony/fascial boundaries.`,
      medical_foundations: `${mechanisms.join(' ')} Platform integration: ${meshNote}`,
      clinical_applied: `Surgical dissection planes, fracture neurovascular risks, and regional compression syndromes in ${chapterTitle.toLowerCase()}: ${clinical}`,
      allied_health: `Palpable surface anatomy, range-of-motion joints, injection/venepuncture safe zones, and rehabilitation mechanics across ${chapterTitle.toLowerCase()}: ${clinical}`,
      graduate_research: `Comparative morphometrics, anatomical variant incidence, embryonic boundary persistence, and surgical fascia continuity across ${chapterTitle.toLowerCase()}. ${meshNote}`,
    },
    keyConcepts: [
      { term: 'Spatial Organization', definition: summary },
      { term: '3D Platform Integration', definition: meshNote },
      { term: 'Surgical / Clinical Relation', definition: clinical },
    ],
    keyFacts: [
      meshNote,
      'Use Isolate, Ghost/X-Ray, Explode, and Clipping Planes inside the 3D Explorer to inspect deep FMA-indexed relations.',
    ],
    mechanisms,
    comparisonTable: { columnA: comp.colA, columnB: comp.colB, rows: comp.rows },
    misconceptions: [
      { misconception: 'Anatomical right/left and planes depend on how the viewer or patient happens to be lying.', correction: 'All directional terms and coronal/sagittal/transverse planes strictly reference the upright standard Anatomical Position (palms anterior), using the SUBJECT’s own right and left.' },
      { misconception: 'Gross human anatomy shows zero individual structural variation.', correction: 'Textbook illustrations represent statistical norms; variations such as coronary artery dominance, cystic-artery origin, or accessory renal arteries are clinically routine.' },
    ],
    clinicalCorrelation: clinical,
    summaryParagraph: `${chapterTitle} unites osteology, myology, neurovascular bundles, and clinical planes across Anatomy 360’s verified 3D BodyParts3D reference meshes and systemic lessons.`,
    keyTakeaways: [
      mechanisms[0] ?? summary,
      meshNote,
      clinical,
    ],
    crossSubjectLinks: [
      { domainId: 'embryology', relation: 'Adult peritoneal reflections, heart chambers, and branchial nerve territories reflect embryonic folding and rotation.' },
      { domainId: 'radiology_imaging', relation: 'Cross-sectional CT and MRI slices project 3D regional anatomy onto standard axial, sagittal, and coronal viewing planes.' },
    ],
    relatedSystems: sys,
    relatedFmaConceptIds: fmas,
    visualFormats: ['3d_anatomy', '2d_diagram', 'clinical_case'],
    diagram: {
      id: `diag-a${num}`,
      title: `${chapterTitle} — Regional Structural Hierarchy & Neurovascular Plane`,
      kind: 'hierarchy',
      caption: `${summary} (${meshNote})`,
      disclaimer: 'Conceptual anatomical organization map paired with FMA-indexed BodyParts3D 3D meshes.',
      nodes: [
        { id: 'n1', label: 'Surface & Osteofascial Frame', sublabel: mechanisms[0]?.slice(0, 62) || summary.slice(0, 62), tone: 'amber' },
        { id: 'n2', label: 'Neurovascular & Visceral Relations', sublabel: mechanisms[1]?.slice(0, 62) || meshNote.slice(0, 62), tone: 'blue' },
        { id: 'n3', label: 'Applied Surgical / Clinical Vulnerability', sublabel: clinical.slice(0, 62), tone: 'rose' },
      ],
      links: [
        { from: 'n1', to: 'n2', label: 'Compartmental boundaries enclose vessels & nerves' },
        { from: 'n2', to: 'n3', label: 'Trauma, compression, or surgical landmark' },
      ],
    },
    assetDisclosure: ANAT_DISCLOSURE,
    activity: {
      title: `3D Mesh Isolation & Relation Check (${chapterTitle})`,
      kind: '3d_inspection',
      prompt: `Launch the Anatomy 360 Explorer, highlight the linked FMA structures for ${chapterTitle}, toggle X-Ray/Ghost surroundings, and verify anterior–posterior and medial–lateral relations.`,
      keyTakeaway: clinical,
    },
    readingKeys: readKeys,
    shortAnswers: [
      { id: `sa-a${num}-1`, prompt: `Describe the boundaries, contents, and major spatial relations in ${chapterTitle}.`, expectedPoints: mechanisms.slice(0, 2), modelAnswer: mechanisms.join(' '), level: 'medical_foundations' },
      { id: `sa-a${num}-2`, prompt: `Contrast ${comp.colA} versus ${comp.colB} anatomically and functionally.`, expectedPoints: comp.rows.map((r) => `${r.dimension}: ${r.primary} vs ${r.comparator}`), modelAnswer: comp.rows.map((r) => `${r.dimension}: ${r.primary} vs ${r.comparator} (${r.clinicalOrFunctionalNote}).`).join(' '), level: 'secondary_premed' },
      { id: `sa-a${num}-3`, prompt: `Predict the specific deficit or surgical complication resulting from injury within ${chapterTitle.toLowerCase()}.`, expectedPoints: [clinical], modelAnswer: clinical, level: 'clinical_applied' },
    ],
    appliedCase: {
      id: `app-a${num}-1`,
      title: `Surgical & Functional Anatomy Reasoning: ${chapterTitle}`,
      scenario: `A teaching clinical vignette traces an injury or surgical incision passing through ${chapterTitle.toLowerCase()} (${meshNote}).`,
      questions: ['Which superficial-to-deep layers are traversed?', 'Which adjacent nerve, vessel, or viscus sits at immediate risk?'],
      workedSolution: `${mechanisms[0]} Applied risk: ${clinical}`,
      level: 'clinical_applied',
    },
    selfChecks: mcqs,
  };
}

